SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE DATABASE IF NOT EXISTS smart_home_store CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smart_home_store;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,email VARCHAR(191) NOT NULL UNIQUE,phone VARCHAR(20),role ENUM('USER','ADMIN') NOT NULL DEFAULT 'USER',status ENUM('ACTIVE','SUSPENDED') NOT NULL DEFAULT 'ACTIVE',privacy_accepted_at TIMESTAMP NULL,marketing_consent BOOLEAN NOT NULL DEFAULT FALSE,marketing_consent_at TIMESTAMP NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_users_created_at (created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS newsletter_subscribers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(191) NOT NULL UNIQUE,first_name VARCHAR(100) NULL,status ENUM('ACTIVE','UNSUBSCRIBED') NOT NULL DEFAULT 'ACTIVE',consent_version VARCHAR(20) NOT NULL,consented_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,unsubscribed_at TIMESTAMP NULL,unsubscribe_token CHAR(64) NOT NULL UNIQUE,last_welcome_sent_at TIMESTAMP NULL,source ENUM('WEBSITE','REGISTER') NOT NULL DEFAULT 'WEBSITE',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_newsletter_status (status),INDEX idx_newsletter_consented_at (consented_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS addresses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,label VARCHAR(50) NOT NULL,recipient_name VARCHAR(200) NOT NULL,phone VARCHAR(20) NOT NULL,address_line VARCHAR(500) NOT NULL,district VARCHAR(150) NOT NULL,province VARCHAR(150) NOT NULL,postal_code VARCHAR(10) NOT NULL,is_default BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_addresses_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sku VARCHAR(50) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,description TEXT,price DECIMAL(10,2) NOT NULL,discount_price DECIMAL(10,2),category VARCHAR(100) NOT NULL,brand VARCHAR(100) NOT NULL,room VARCHAR(100) NOT NULL DEFAULT 'ห้องนั่งเล่น',stock INT NOT NULL DEFAULT 0,rating DECIMAL(2,1) NOT NULL DEFAULT 0,status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_number VARCHAR(30) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NOT NULL,grand_total DECIMAL(10,2) NOT NULL,status ENUM('PENDING_PAYMENT','PAID','PREPARING','SHIPPING','DELIVERED','CANCELLED') NOT NULL DEFAULT 'PENDING_PAYMENT',payment_method ENUM('PROMPTPAY','CARD','WALLET') NULL,payment_reference VARCHAR(50) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_orders_user FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,product_name VARCHAR(255) NOT NULL,price DECIMAL(10,2) NOT NULL,quantity INT NOT NULL,CONSTRAINT fk_order_items_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE,CONSTRAINT fk_order_items_product FOREIGN KEY (product_id) REFERENCES products(id)) ENGINE=InnoDB;
ON DUPLICATE KEY UPDATE name=VALUES(name),description=VALUES(description),price=VALUES(price),discount_price=VALUES(discount_price),category=VALUES(category),brand=VALUES(brand),room=VALUES(room),stock=VALUES(stock),rating=VALUES(rating),status='ACTIVE';
